package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.ApiResponse;import in.kabadiwala.connect.repository.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.Map; @RestController @RequestMapping("/api/v1/profile") public class ProfileController {private final UserRepository u;private final CollectorProfileRepository c;private final RecyclerProfileRepository r;public ProfileController(UserRepository u,CollectorProfileRepository c,RecyclerProfileRepository r){this.u=u;this.c=c;this.r=r;}@GetMapping ApiResponse<?> me(Authentication a){var user=u.findById(a.getName()).orElseThrow();Object profile=user.role.name().equals("RECYCLER")?r.findByUserId(user.id).orElse(null):c.findByUserId(user.id).orElse(null);return ApiResponse.ok("Profile",Map.of("user",user,"profile",profile==null?Map.of():profile));}@PatchMapping ApiResponse<?> update(Authentication a,@RequestBody Map<String,String>b){var x=u.findById(a.getName()).orElseThrow();if(b.containsKey("fullName"))x.fullName=b.get("fullName");if(b.containsKey("language"))x.language=b.get("language");u.save(x);return ApiResponse.ok("Profile updated",x);}}
